use crate::token::{format_token, Token};

pub fn login(raw: &str) -> Result<String, String> {
    let token = Token::verify(raw, 0)?;
    Ok(format!("session:{}", format_token(token.raw.as_bytes())))
}

use crate::token::Token;

pub fn bind(raw: &str) -> Result<Token, String> {
    Token::verify(raw, 0)
}

pub fn format_token(raw: &[u8]) -> String {
    format!("<redacted token: {} bytes>", raw.len())
}

pub struct Token {
    pub raw: String,
    pub expires_at: u64,
}

impl Token {
    pub fn verify(raw: &str, now: u64) -> Result<Self, String> {
        if raw.is_empty() {
            return Err("empty".into());
        }

        let expires_at = match raw.rsplit_once(':') {
            Some((value, expiry)) if !value.is_empty() && !expiry.is_empty() => expiry
                .parse::<u64>()
                .map_err(|_| "invalid expiration".to_string())?,
            Some(_) => return Err("invalid expiration".into()),
            None => u64::MAX,
        };

        if now >= expires_at {
            return Err("expired".into());
        }

        Ok(Self {
            raw: raw.to_string(),
            expires_at,
        })
    }
}
